# Check the Markdown instance structure
import markdown
md = markdown.Markdown(extensions=['toc', 'attr_list'])

print("Markdown attributes:")
for attr in dir(md):
    if not attr.startswith('_'):
        val = getattr(md, attr)
        if hasattr(val, '__iter__') and not isinstance(val, str):
            try:
                items = list(val)
                print(f"  {attr}: {type(items)} with {len(items)} items")
            except:
                print(f"  {attr}: {type(val)}")
        else:
            print(f"  {attr}: {type(val)}")
